package com.vms.vendorcontractmanagement.controller; import com.vms.vendorcontractmanagement.dto.DepartmentDtos.*; import com.vms.vendorcontractmanagement.dto.VendorDtos; import com.vms.vendorcontractmanagement.service.*; import jakarta.validation.*; import lombok.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor public class DepartmentController {final DepartmentService service;@GetMapping public List<Response> list(){return service.list();}@GetMapping("/{id}") public Response get(@PathVariable Long id){return service.get(id);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @ResponseStatus(HttpStatus.CREATED) public Response create(@Valid @RequestBody Request r){return service.create(r);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public Response update(@PathVariable Long id,@Valid @RequestBody Request r){return service.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}@GetMapping("/{id}/vendors") public List<VendorDtos.Response> vendors(@PathVariable Long id){return service.vendorList(id);}@PostMapping("/{id}/vendors/{vendorId}") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @ResponseStatus(HttpStatus.NO_CONTENT) public void assign(@PathVariable Long id,@PathVariable Long vendorId){service.assign(id,vendorId);}@DeleteMapping("/{id}/vendors/{vendorId}") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(@PathVariable Long id,@PathVariable Long vendorId){service.remove(id,vendorId);} }
